import { analysisGuide as g } from "@/lib/question-bank/guide";

export const MORE_GUIDES: Record<string, { guideAr: string; guideEn: string }> = {
  "2-1-a01": g("المصادقة متعددة العوامل", "كلمة المرور تحت الشاشة تتسرق بالنظر. عامل واحد مش كفاية.", "أمين المكتبة يضيف رسالة على الموبايل زي فتح منصة الدرجات.", "Multi-factor authentication", "A password under the screen is stolen by looking. One factor is not enough.", "The librarian adds a phone code, like opening the marks platform."),
  "2-1-a02": g("التشفير المتماثل وغير المتماثل", "لو الطرفان اتفقوا على سر يكفي مفتاح واحد. لو ما اتقابلوش نحتاج زوج مفاتيح.", "نسخة المعمل بمفتاح واحد. شكوى ولي الأمر تتشفر بالمفتاح العام.", "Symmetric and asymmetric encryption", "A shared secret needs one key. Strangers need a public and private pair.", "A lab backup uses one key. A parent complaint uses the public key."),
  "2-1-a03": g("المصادقة", "التشفير يخفي الكلام، لكنه ما يثبتش مين اللي بعت.", "رسالة مشفرة تدّعي إنها من رائد الفصل وتطلب رقم البطاقة: متتبعهاش من غير تحقق.", "Authentication", "Encryption hides the words but does not prove who sent them.", "An encrypted message claims to be the class tutor and asks for an ID. Do not follow it without a check."),
  "2-1-a04": g("التجزئة", "الاتجاه الواحد يمنع رجوع كلمة المرور بعد السرقة. نقارن البصمة بس.", "خادم المدرسة يحفظ بصمة الكلمة، مش الكلمة نفسها.", "Hashing", "One-way storage stops anyone recovering the password after theft. We only compare the fingerprint.", "The school server stores the password fingerprint, not the clear password."),
  "2-1-a05": g("الشهادة الرقمية", "هي اللي تربط المفتاح العام باسم الموقع الموثوق.", "لو الشهادة مش بنفس اسم موقع المدرسة، المتصفح يحذر ومتكتبش كلمة المرور.", "Digital certificate", "It binds a public key to a trusted site name.", "If the certificate does not match the school site name, the browser warns you and you do not type the password."),
  "2-1-a06": g("المصادقة متعددة العوامل", "شيء تعرفه، شيء تملكه، شيء أنت عليه. سرقة واحد منهم مش بتفتح الحساب.", "كلمة + رسالة موبايل + بصمة. ورقة المكتبة المسروقة لوحدها تفشل.", "Multi-factor authentication", "Something you know, have, and are. Stealing one factor does not open the account.", "Password plus phone code plus fingerprint. A stolen library paper alone fails."),
  "2-1-a07": g("انتحال الهوية", "التشفير يحمي الطريق، ومش بيثبت الزائر.", "ملف العيادة المشفر لو اتفتح باسم المريض بس، أي حد يعرف الاسم يدخله.", "Impersonation", "Encryption protects the path and does not prove the visitor.", "If the clinic file opens for anyone who knows the patient's name, an impostor gets in."),
  "2-1-a08": g("التشفير غير المتماثل", "المفتاح الخاص يفك كل الرسائل. لو اتنشر، السر يقع.", "المفتاح الخاص يقعد على خادم المدرسة. الملفات الواردة تتشفر بالمفتاح العام بس.", "Asymmetric encryption", "The private key opens every message. If it is published, the secret is gone.", "The private key stays on the school server. Incoming files are encrypted with the public key only."),
  "2-2-a01": g("الأمن متعدد الطبقات", "جدار واحد لو وقع يكشف الشبكة لو الأجهزة من غير كلمة مرور.", "خادم الدرجات وراه جدار، والأجهزة جوه لازم يكون ليها قفل برضه.", "Layered security", "One firewall is not enough if the inner machines have no passwords.", "The marks server sits behind a firewall, and the inner lab PCs still need locks."),
  "2-2-a02": g("شبكة خاصة افتراضية", "شبكة المقهى أو الفندق مش موثوقة. النفق المشفر يخلي الحركة كأنها جوه المدرسة.", "المعلمة تصحح من البيت عبر النفق، مش على واي فاي الفندق المكشوف.", "VPN", "Cafe or hotel Wi-Fi is untrusted. An encrypted tunnel makes traffic behave as if it were on campus.", "The teacher marks from home through the tunnel, not on open hotel Wi-Fi."),
  "2-2-a03": g("مبدأ أقل صلاحية", "زيادة الصلاحية تضخم الضرر لو الحساب اتسرق.", "أمين المكتبة مش محتاج يعدل درجات الفيزياء «للاحتياط».", "Least privilege", "Extra rights magnify harm if the account is stolen.", "The librarian does not need physics-mark rights «just in case»."),
  "2-2-a04": g("تقسيم الشبكة", "عزل الجزء المصاب يمنع الوصول لخادم النتائج.", "معمل اتصاب يتفصل فورًا عن خادم الدرجات.", "Segmentation", "Isolating the infected part stops the breach reaching the results server.", "An infected lab is cut off from the marks server at once."),
  "2-2-a05": g("الأمن بالتصميم", "إضافة القفل بعد ما أولياء الأمور يدخلوا أضعف وأغلى.", "البوابة تطلع بكلمات مرور وصلاحيات من أول يوم، مش في آخر أسبوع.", "Security by design", "Bolting on passwords after parents arrive is weaker and costlier.", "The portal launches with passwords and rights from day one, not in the last week."),
  "2-2-a06": g("الأمن متعدد الطبقات", "محيط، شبكة داخلية، أجهزة، بيانات. لو طبقة وقعت، اللي بعدها توقف المهاجم.", "قفل باب المعمل مش بيحمي مجلد مشترك من غير تشفير.", "Layered security", "Perimeter, internal network, devices, data. If one layer falls the next should still stop the attacker.", "Locking the lab door does not protect an unencrypted shared folder."),
  "2-2-a07": g("إغلاق المنافذ", "منفذ مفتوح من غير خدمة باب جاهز للمسح الآلي.", "منفذ سطح المكتب البعيد لو مش مستخدم يتقفل، مش يتغيّر رقمه وبس.", "Closing unused ports", "An open unused port is a door ready for automated scans.", "An unused remote-desktop port is closed, not just renumbered."),
  "2-2-a08": g("التحديث الأمني", "تأجيل الرقعة يسيب ثغرة معروفة للمهاجم.", "معمل المدرسة يتحدث قبل الامتحانات، مش بعدها.", "Security patching", "Delaying a patch leaves a hole attackers already know.", "The school lab is patched before exams, not after."),
  "2-3-a01": g("الحادث", "إخفاء التسريب يوسّع مين شاف البيان.", "كشوف الغياب لو اتسربت، الإدارة تبلغ فورًا ومتستناش «تهدأ الأمور».", "Incident", "Hiding a leak widens who saw the data.", "If attendance sheets leak, the office reports at once and does not wait until things calm down."),
  "2-3-a02": g("إدارة المخاطر", "بعد التقدير نقبل أو نخفف أو ننقل. التجاهل مش خيار.", "طابعة معزولة من غير بيانات حية تتقبل. كلمة واحدة لكل المنصات تتخفف.", "Risk management", "After an estimate we accept, reduce, or transfer. Ignoring is not a choice.", "An isolated printer with no live data can be accepted. One password for every platform must be reduced."),
  "2-3-a03": g("حفظ الأدلة", "مسح القرص أول لحظة يمسح أثر الدخول.", "نصور القرص ونسجل الوقت قبل أي تهيئة.", "Preserving evidence", "Wiping the disk at once erases how the malware entered.", "Image the disk and note the time before any format."),
  "2-3-a04": g("خطة الاستجابة", "ورقة على الرف من غير تمرين تسقط وقت الهلع.", "المدرسة تعمل تجربة: مين يعزل، مين يبلغ، مين ما يمسحش.", "Response plan", "A shelf paper with no drill fails in a panic.", "The school rehearses: who isolates, who reports, who does not wipe."),
  "2-3-a05": g("الاحتواء", "فصل الجهاز يوقف الاتساع ويبقي الأدلة.", "اللابتوب المصاب يتفصل عن الطابعة قبل التنظيف.", "Containment", "Pulling the device off stops spread and keeps evidence.", "The infected laptop is taken off the printer before cleanup."),
  "2-3-a06": g("إدارة المخاطر", "مسح أيقونة الفيروس يعالج العرض لو السبب لسه مفتوح.", "بعد التنظيف نسأل: أي منفذ أو كلمة فضلت مفتوحة؟", "Risk management", "Deleting the virus icon treats the symptom if the cause stays open.", "After cleanup we ask: which port or password stayed open?"),
  "2-3-a07": g("خطة الاستجابة", "الخطوات مكتوبة: اكتشف، احتوِ، أزل، استعد، راجع. الذاكرة تسقط في الهلع.", "مديرية تعتمد على تليفون وكيل واحد تتعطّل لو غاب.", "Response plan", "Written steps: detect, contain, eradicate, recover, review. Memory fails in a panic.", "A directorate that relies on one deputy's phone stalls if he is away."),
  "2-3-a08": g("خطة الاستجابة", "بعد التشغيل نراجع إيه اللي فشل عشان الحادث ما يتكررش.", "اجتماع بعد رجوع المعمل يسأل عن السبب، مش يكتفي إن الأجهزة اشتغلت.", "Response plan", "After power-on we review what failed so the incident does not repeat.", "The meeting after the lab returns asks about the cause, not only whether machines turned on."),

  "3-1-a01": g("طبقات التطبيق", "العرض يجمع الطلب. التطبيق يفحص الصلاحية. البيانات تحفظ السجل.", "ضغط حفظ الحضور: الشاشة تجمع، الخادم يقرر، القاعدة تخزن.", "Application layers", "Presentation collects the request. Application checks the right. Data stores the record.", "Save attendance: the screen collects, the server decides, the database stores."),
  "3-1-a02": g("الواجهة والخادم", "الواجهة تعرض. الخادم يحفظ الرقم الحقيقي. تعديل الشاشة مش سجل.", "طالب يغيّر الدرجة في المتصفح. الخادم يرفض لأن الحقيقة عنده.", "Frontend and backend", "The frontend displays. The backend stores the real mark. An edited screen is not the record.", "A student changes a mark in the browser. The server refuses because it holds the truth."),
  "3-1-a03": g("الخادم / الخلفية", "المتصفح مكشوف. أي زائر يقرأ المصدر. السر يعيش على الخادم.", "مفتاح أو كلمة مرور جوه صفحة التسجيل تتنسرق من عرض المصدر.", "Backend", "The browser is public. Any visitor can read the source. Secrets live on the server.", "An API key or password inside the registration page is stolen from View Source."),
  "3-1-a04": g("العميل-الخادم", "المتصفح يطلب. الخادم يقرر ويكتب في البيانات. الصفحة لوحدها ما تملكش المقعد.", "حجز حصة المعمل: الطلب من المتصفح، القرار من الخادم.", "Client–server", "The browser asks. The server decides and writes to the data layer. The page alone does not own the seat.", "Lab booking: the request comes from the browser, the decision from the server."),
  "3-1-a05": g("طبقات التطبيق", "العرض يوري العدد. التطبيق يحسم التسابق. البيانات تبقي المقعد بعد قفل التبويب.", "طالبان على آخر مقعد: اللي الخادم حفظه هو اللي يثبت.", "Application layers", "Presentation shows the count. Application settles the race. Data keeps the seat after the tab closes.", "Two students on the last seat: whatever the server stored is what stands."),
  "3-1-a06": g("قاعدة البيانات", "بطاقة لوحة التحكم عرض قديم. الحقيقة في البيانات. نحدّث العرض من الخادم.", "البطاقة كتبت 12 غياب والقاعدة 15. نعتمد القاعدة.", "Database", "A dashboard card is a stale view. Truth lives in the data. Refresh the view from the server.", "The card says 12 absences and the database says 15. Trust the database."),
  "3-1-a07": g("قاعدة البيانات", "التبويب واللقطة ذاكرة مؤقتة. الدرجات تفضل في القاعدة للترم الجاي.", "متحفظش درجات منتصف الترم في لقطة شاشة.", "Database", "A tab or a screenshot is temporary. Marks stay in the database for next term.", "Do not keep midterm marks only in a screenshot."),
  "3-1-a08": g("فصل الواجهة عن الخادم", "فريق الشكل يغيّر الشاشة من غير ما يكسر الحفظ. فريق الخادم يملك المنطق.", "شاشة الدرجات تتغير ألوانها، وخدمة العلامات تفضل تحفظ صح.", "Splitting frontend and backend", "The look team can change the screen without breaking storage. The server team owns the logic.", "The marks screen can change colour while the marks service still stores correctly."),
  "3-2-a01": g("بروتوكول ويب آمن", "البروتوكول العادي مكشوف. الآمن يشفّر الطريق. لو مفيش قفل متعملش كلمة مرور.", "درجات على شبكة مقهى من غير قفل: متكتبش السر.", "Secure web protocol", "Plain web traffic is visible. The secure version encrypts the path. If there is no lock, do not type a password.", "Marks on cafe Wi-Fi with no lock: do not type the secret."),
  "3-2-a02": g("طرق الطلب", "القراءة تجيب من غير تغيير مقصود. الإرسال ينشئ. التعديل الجزئي يغيّر حقل. الحذف بعد إذن الخادم.", "كشف حضور يُقرأ. حجز معمل يُرسل. رقم ولي الأمر يتحدث. الساعة تُلغى بعد إذن.", "Request methods", "A read fetches without intending to change. A send creates. A partial update changes one field. Delete needs the server's permission.", "Read an attendance list. Send a lab booking. Update a parent number. Cancel the hour after permission."),
  "3-2-a03": g("رمز الحالة", "404 المورد مش على العنوان. 500 الخادم فشل. 200 نجاح.", "قائمة المعمل تفشل على هاتفين: شوف الرمز قبل ما تلوم الشبكة.", "Status code", "404 means the resource is not at that address. 500 means the server failed. 200 means success.", "The lab list fails on two phones: read the code before blaming the network."),
  "3-2-a04": g("واجهة برمجية", "الاتفاق على الأسماء والأشكال لازم يكون مكتوب. التخمين بيكسر التفاهم.", "التطبيق يبعت كلمة والخادم مستني كلمة تانية: العقد ناقص.", "Programming interface", "Names and shapes must be agreed in writing. Guessing breaks the contract.", "The app sends one field name and the server waits for another: the contract is missing."),
  "3-2-a05": g("تحديث المورد", "البديل الكامل يستبدل الكل. التعديل الجزئي يغيّر حقل. متمسحش الطالب عشان رقم اتغيّر.", "نقل الصف بديل كامل. تغيير رقم التليفون تعديل جزئي.", "Updating a resource", "A full replace swaps the whole record. A partial update changes one field. Do not delete a student to change a number.", "Moving a class is a full replace. Changing a phone number is a partial update."),
  "3-2-a06": g("الجلسة", "الجلسة تحفظ الدخول عبر الطلبات. على جهاز مشترك لازم تنتهي. الكوكي على خط مكشوف خطر.", "المعلم يخلص ويخرج من جهاز المعمل، مش يسيب الدخول مفتوح.", "Session", "A session keeps the login across requests. On a shared PC it must end. A cookie on a clear line is dangerous.", "The teacher signs out of the lab PC and does not leave the login open."),
  "3-2-a07": g("عقد البيانات", "شكل التاريخ لازم يكون واحد. من غير اتفاق التطبيقان ما يفهموش بعض.", "الواجهة تبعت يوم/شهر والخادم مستني سنة-شهر-يوم: الطلب يقع.", "Data contract", "The date shape must be one agreed form. Without a contract the two apps do not understand each other.", "The frontend sends day/month and the server waits year-month-day: the request fails."),
  "3-2-a08": g("طرق الطلب", "القراءة مش للإنشاء. الحذف محتاج قرار خادم، مش زر مخفي.", "حفظ الحضور بطريقة قراءة يخفي التعديل في العنوان وده غلط.", "Request methods", "A read is not for creating. Delete needs a server decision, not a hidden button.", "Saving attendance with a read method hides the change in the address, and that is wrong."),
  "3-3-a01": g("هيكل الصفحة", "العناوين والجداول والقوائم تحمل المعنى. مربعات الشكل لوحدها مش كفاية للإنسان ولا لقارئ الشاشة.", "صفحة درجات من مربعات عريضة من غير عناوين حقيقية تفشل.", "Page structure", "Headings, tables, and lists carry meaning. Styled boxes alone fail a human and a screen reader.", "A marks page of bold boxes with no real headings fails."),
  "3-3-a02": g("هيكل الصفحة وتنسيقها وتفاعلها", "الهيكل للمعنى. التنسيق للون والشبكة. لغة التفاعل بعد التحميل. قرار الحضور على الخادم.", "متخليش اللون أو سكربت الشاشة يغني عن حفظ الخادم.", "Page structure, style, and action", "Structure is meaning. Style is colour and layout. Action runs after load. Attendance decisions stay on the server.", "Do not let colour or a screen script replace server storage."),
  "3-3-a03": g("إتاحة الوصول", "المسار لازم يمشي بلوحة المفاتيح. لو محتاج فأرة، الاختبار فشل.", "تسجيل الشعبة يتجرب من غير ماوس قبل عرض المدير.", "Accessibility", "The path must work with a keyboard. If it needs a mouse, the simple test failed.", "Class registration is tested without a mouse before the head sees it."),
  "3-3-a04": g("إتاحة الوصول", "من غير رأس الجدول الأرقام يتيمة. من غير تسمية الاسم يختفي.", "جدول الدرجات يستخدم رؤوس حقيقية، وحجز المعمل يربط الاسم بالحقل.", "Accessibility", "With no table headers the numbers are orphans. With no label the name vanishes.", "The marks table uses real headers, and lab booking ties the name to the field."),
  "3-3-a05": g("التصميم المتجاوب", "نبدأ من الشاشة الضيقة والنص الكبير، بعدين نوسّع. القرص بالإصبعين مش بديل.", "جدول الحضور على الموبايل يتقرأ من غير ما يتقص.", "Responsive design", "Start from a narrow screen and readable text, then widen. Pinch-zoom is not a layout.", "The attendance table stays readable on a phone without being cropped."),
  "3-3-a06": g("إتاحة الوصول", "اللون لوحده يفشل. نضيف كلمة ونرفع التباين.", "المتأخر يتكتب «متأخر»، مش نقطة حمراء بس.", "Accessibility", "Colour alone fails. Add a word and raise contrast.", "Late is written as «late», not only a red dot."),
  "3-3-a07": g("هيكل الصفحة", "الزر الحقيقي يتقفله التركيز. الصورة مكان الزر تخفي الفعل عن لوحة المفاتيح.", "حفظ الحضور زر حقيقي، مش صورة.", "Page structure", "A real button can take focus. An image standing in for a button hides the action from the keyboard.", "Save attendance is a real button, not a picture."),
  "3-3-a08": g("إتاحة الوصول", "قائمة تظهر بالمرور بس تقفل الموبايل ولوحة المفاتيح. الهيكل يتكتب أولاً.", "قائمة الأدوات تبقى ظاهرة وقابلة للتركيز من غير فأرة.", "Accessibility", "A menu that appears only on hover fails a phone and a keyboard. Structure comes first.", "The tools menu stays visible and focusable without a mouse."),

  "4-1-a01": g("اختيار الوسيط", "الأرقام تقارن في جدول أو رسم. الصوت للتعليق مش للقيم. البحث جوه مقطع طويل غالي.", "نتائج منتصف الترم تطلع في جدول، والتعليق الصوتي يشرح الجدول مش يستبدله.", "Choosing the medium", "Numbers are compared in a table or chart. Audio is commentary, not values. Hunting inside a long clip costs time.", "Midterm results go in a table, and the voice clip explains the table instead of replacing it."),
  "4-1-a02": g("حجم الملف والجودة", "البكسل الزائد بعد حد الشاشة مش بيزود المعنى، وبيبطّئ الفتح على شبكة ضعيفة.", "بانر الترحيب يتضغط لحجم الشاشة، مش يتساب تمانية ميجا على الجيل الثالث.", "File size and quality", "Extra pixels past the screen add no meaning and slow opening on a weak network.", "The welcome banner is compressed to screen size, not left at eight megabytes on 3G."),
  "4-1-a03": g("النص البديل", "اسم ملف الكاميرا مش وصف. اللي بيستخدم قارئ شاشة محتاج جملة توضح الصورة.", "نكتب: مشروع الطاقة الشمسية لطالب الصف الثاني، مش رقم الكاميرا.", "Alt text", "A camera filename is not a description. A screen-reader user needs a sentence that names the image.", "Write: solar-energy project by a second-year student, not the camera number."),
  "4-1-a04": g("النص البديل", "الإتاحة تتكتب مع الإطلاق. الصورة اللي ليها معنى لازم تتوصف من أول يوم، مش بعد الحفل.", "صور الحفل تتنشر بجمل بديلة جاهزة، مش «هنضيف الوصف بعدين».", "Alt text", "Access is due at launch. A meaningful image must be described from day one, not after the concert.", "Concert photos go out with ready alt sentences, not «we will add the description later»."),
  "4-1-a05": g("اختيار الوسيط", "المسح الضبابي ثقيل ومش مقروء على الموبايل ولا لقارئ الشاشة.", "قائمة الكانتين تبقى نصًا واضحًا أو صورة حادة خفيفة.", "Choosing the medium", "A blurry scan is heavy and fails on a phone and with a screen reader.", "The canteen menu stays clear text or a sharp light image."),
  "4-1-a06": g("اختيار الوسيط", "مهمة الراكب معرفة الساعة التالية. الحركة اللي بتدور من غير ما تقف زينة بتخفي البيان.", "مواعيد الأتوبيس جدول ثابت، مش رسوم بتلف ومش بتثبت على الساعة الجاية.", "Choosing the medium", "The rider's task is the next time. A looping animation that never settles hides the fact.", "The bus times stay a still table, not a clip that never lands on the next hour."),
  "4-1-a07": g("ضغط الملف", "الضغط الصح يبقي الأداء ويسرّع التنزيل. منع أي ضغط بدعوى الجودة بيخلّي الملف ما يتفتحش.", "تسجيل الكورال يتضغط بحيث الصوت يفضل واضح من غير ملف عملاق.", "File compression", "Good compression keeps the performance and speeds the download. Banning all compression in the name of quality leaves a file nobody can open.", "The choir recording is compressed so the voices stay clear without a giant file."),
  "4-1-a08": g("اختيار الوسيط", "خطوات اليوم الأول محتاجة نص أو مقطع قصير مضغوط. الزمن والحجم جزء من جودة الدليل.", "دليل الطالب الجديد ورقة قصيرة أو فيديو مضغوط، مش فيلم صامت دقايق على باب الإدارة.", "Choosing the medium", "First-day steps need text or a short compressed clip. Time and size are part of the guide's quality.", "The new-student guide is a short sheet or a compressed clip, not a silent cinema video of the office door."),
  "4-2-a01": g("تجربة المستخدم", "ست قوائم قبل زر حاضر تكسر الرحلة. المهمة الواحدة لازم توصل بأقل نقرات.", "الحضور يفتح على زر حاضر، مش ست قوائم قبل ما يظهر.", "User experience", "Six menus before Present break the journey. One task should arrive in the fewest clicks.", "Attendance opens on Present, not six menus first."),
  "4-2-a02": g("تجربة المستخدم وواجهة المستخدم", "التجربة: هل وصل للنموذج؟ الواجهة: فين الزر ولونه واسمه؟ الجمال مش بينقذ رحلة مكسورة.", "صفحة الرسوم تخلي ادفع ظاهر، مش تضيع ولي الأمر بين نادي الشطرنج وأخبار الحفل.", "UX and UI", "UX: did they reach the form? UI: where is the button, its colour, its label? Pretty controls do not save a broken journey.", "The fees page puts Pay in sight, and does not lose the parent between chess club and concert news."),
  "4-2-a03": g("الاتساق", "القائمة اللي بتقفز مكانها بعد الدخول بتخلّي المستخدم يتعلم من جديد كل مرة.", "القائمة تفضل في نفس المكان قبل الدخول وبعده.", "Consistency", "A menu that jumps after login makes the user relearn every time.", "The menu stays in the same place before and after login."),
  "4-2-a04": g("الاتساق", "ثبات المكان ولون الزر الرئيسي يسرّع المهمة. المفاجأة تصلح لمعرض مش لحضور يومي.", "زر حاضر يفضل أخضر وفي نفس الركن كل يوم.", "Consistency", "A stable place and primary colour speed the task. Surprise fits a gallery, not daily attendance.", "Present stays green in the same corner every day."),
  "4-2-a05": g("اختبار الاستخدام", "نسجّل فين وقفت العين، امتى اتأخر، وامتى قفل الصفحة. الضياع يبقى تعديل في ترتيب الشاشة.", "لو الزميل قفل صفحة الرسوم من غير ما يلاقي ادفع، الزر يتقرب ويتكبّر.", "Usability testing", "Log where the eye stops, when they pause, and when they close. Getting lost becomes a change in visual order.", "If a classmate closes fees without finding Pay, the button moves closer and grows."),
  "4-2-a06": g("التسلسل البصري", "الحجم والموضع والتسمية يورّوا المهمة. اللون لوحده مش بيفرّق حاضر من متأخر.", "زر سجّل حضورك أكبر من إعلان الكافتيريا، ومتكتب جنب النقطة كلمة.", "Visual hierarchy", "Size, place, and label show the task. Colour alone does not split Present from Late.", "Mark your attendance is larger than the cafeteria advert, and the dot has a word beside it."),
  "4-2-a07": g("تجربة المستخدم", "تسع نقرات وتعليمات مخفية عشر ثواني بتضيّع الوقت. الخطوات تظهر في الصفحة.", "جدول الحصص يتنزّل من رابط ظاهر، مش من نشرات قديمة وتلميح متأخر.", "User experience", "Nine clicks and a ten-second hidden tip waste time. The steps should sit on the page.", "The timetable downloads from a visible link, not old newsletters and a late tooltip."),
  "4-2-a08": g("إتاحة الوصول", "الرحلة القصيرة تتحسب للوحة المفاتيح كمان، مش للفأرة بس.", "الطالب يوصل للحضور من التاب من غير ماوس.", "Accessibility", "A short journey is counted for the keyboard too, not only the mouse.", "The student reaches attendance from the Tab key without a mouse."),
  "4-3-a01": g("قابلية الاستخدام", "التقييم: إتمام، زمن، أخطاء. التصويت على الشكل ذوق، مش قياس.", "نحسب كام طالب سجّل حضور، مش مين عجبه لون الصفحة.", "Usability", "Evaluation is completion, time, and errors. A look vote is taste, not a measure.", "We count how many students marked attendance, not who liked the page colour."),
  "4-3-a02": g("اختبار أ/ب", "نقسّم الزوار ونقيس الإتمام وحجم العينة. صديقين في الفسحة مش فائز.", "نجرّب سجّل الآن وأنا هنا على صفوف كتير، ونشوف أنهي زر خلّص المهمة.", "A/B testing", "Split visitors and measure completion and sample size. Two friends at break are not a winner.", "Try Mark now and I am here across many classes, and see which button finishes the task."),
  "4-3-a03": g("إتاحة الوصول", "قارئ الشاشة ولوحة المفاتيح بند في الدرجة. فشل الحجز من غير فأرة نقص قابلية استخدام.", "قائمة التقييم تحط الإتاحة جنب الأناقة، مش في حاشية.", "Accessibility", "The screen reader and keyboard sit on the score line. A failed lab booking without a mouse is missing usability.", "The score sheet puts access beside elegance, not in a footnote."),
  "4-3-a04": g("زمن المهمة", "الزمن قبل تقريب الزر وبعده دليل نجاح أو فشل. الزمن يشمل التصحيح، مش أول نقرة بس.", "لو الحضور نزل من أربع دقايق لأربعين ثانية، ده نجاح، مش حجم الشعار.", "Task time", "Time before and after moving the button is success or failure. Time includes repair, not only the first click.", "If attendance drops from four minutes to forty seconds, that is success, not logo size."),
  "4-3-a05": g("معدل الإتمام", "خمس نجوم رضا مع نص الطلاب ما بيبعتوش الاستمارة رضا ناقص.", "نستنى نسبة اللي خلّصوا استمارة النادي جنب نجوم الاستطلاع.", "Completion rate", "Five satisfaction stars with half the students leaving the form is incomplete satisfaction.", "We keep the share who finished the club form beside the survey stars."),
  "4-3-a06": g("عدد الأخطاء", "الأخطاء وكلفة إصلاح التاريخ معيار. متخبيش رسالة الغلط لأنها محرجة.", "بعد تغيير منتقي التاريخ نحسب كام ولي أمر غلط وكم ثانية أصلحت.", "Error count", "Errors and the cost of fixing the date are a standard. Do not hide the error because it is embarrassing.", "After changing the date picker we count how many parents erred and how many seconds they spent repairing."),
  "4-3-a07": g("اختبار أ/ب", "عينة صديقين ذوق متنكّر. لازم مقياس وعدد قبل إعلان النسخة.", "البنفسجي ما يتعلنش فائز إلا بعد ما نقيس إتمام أولياء الأمور.", "A/B testing", "A two-friend sample is taste in disguise. Demand a measure and a count before naming the version.", "Purple is not declared the winner until parent completion is measured."),
  "4-3-a08": g("إتاحة الوصول", "مدح الخط في ليلة أولياء الأمور مش بيرفع الدرجة لو حد مستبعد من القراءة.", "الدرجة تفضل تحسب مين يقدر يقرأ ويكمل، مش التصفيق على اللون.", "Accessibility", "Praise for the font at parents' evening does not raise the score if someone is excluded from reading.", "The score still counts who can read and finish, not applause for colour."),
  "4-4-a01": g("حلقة التحسين", "صمّم، اختبر، تعلّم، حسّن. العثرة الأولى فرضية، مش حكم بهدم الموقع كله.", "فشل تسجيل يوم الرياضة يعدّل الصفحة، مش يهدم الموقع في العطلة.", "Improvement loop", "Design, test, learn, improve. The first stumble is a hypothesis, not a verdict to tear the site down.", "Failed sports-day registration edits the page; it does not demolish the site over the weekend."),
  "4-4-a02": g("تغيير واحد لكل دورة", "لو اتحرك اللون والموضع والنص والخط مع بعض، السبب يضيع.", "الدورة الأولى تغيّر اسم الزر بس. بعد ما يثبت، نحرّك مكانه.", "One change per cycle", "If colour, place, wording, and font all move, the cause is lost.", "The first cycle changes the button label only. After it is proven, we move its place."),
  "4-4-a03": g("دليل القرار", "إصلاح الدليل يتقدم على قائمة الأمنيات. الثلاثين فكرة دورات لاحقة، مش دفعة امتحانات.", "لو التسمية غامضة، نصلح الاسم الأول، مش ننفّذ اللوحة كلها في أسبوع الامتحان.", "Decision evidence", "The evidence fix comes before the wish list. Thirty ideas belong in later cycles, not one exam-week batch.", "If the attendance label is unclear, we fix the name first, not ship the whole board in exam week."),
  "4-4-a04": g("النموذج الأولي", "الورق المقوى رخيص وسريع بيكشف الضياع. نقل زر على السبورة أرخص من إصلاحه بعد الأجهزة.", "تدفق الاستئذان يتجرب على الكرتون قبل شراء رخصة أو ربط قاعدة بيانات.", "Prototype", "Cardboard is cheap and fast at revealing getting lost. Moving a button on the board is cheaper than repairing it after devices.", "The permission flow is tried on cardboard before buying a licence or wiring a database."),
  "4-4-a05": g("حلقة التحسين", "نقطة الخروج فرضية الدورة. الزينة فوق خانة السر بتغطي السبب بدل ما تسهّل الخطوة.", "لو الناس بتمشي عند كلمة المرور، نسهّل الخانة، مش نضيف رسوم متحركة فوقها.", "Improvement loop", "The leave point is the cycle's hypothesis. Animation over the password covers the cause instead of simplifying the step.", "If visitors leave at the password, we simplify the field; we do not add motion over it."),
  "4-4-a06": g("دليل القرار", "السجل يكتب السبب والدليل والتغيير. جملة «عجبنا المكان» بترجع الذوق في الدورة الجاية.", "نكتب: سبعة من عشرة تجاوزوا الزر، لذلك تغيّر شكله.", "Decision record", "The record names reason, evidence, and change. «We liked the new place» returns taste in the next cycle.", "We write: seven of ten skipped the button, so its look changed."),
  "4-4-a07": g("حلقة التحسين", "الموقع ما يننشرش ويتنسى. الأثر يبرد لو القياس استنى آخر الترم.", "تقارير المغادرة تتقرا من يوم الأحد، مش تتساب لحد امتحانات آخر الترم.", "Improvement loop", "A site is not launched and forgotten. The trail goes cold if measurement waits until exams.", "Leave reports are read from Sunday, not left until end-of-term exams."),
  "4-4-a08": g("دليل القرار", "من غير رقم، الفريق يرجع للشعور بهدم أو لقائمة أمنيات.", "قبل الدورة الجديدة نكتب ليه قرّبنا رابط الجدول وكم ثانية قلت.", "Decision record", "Without a number the team returns to a feeling of teardown or to a wish list.", "Before a new cycle we write why the timetable link moved closer and how many seconds dropped."),

  "5-1-a01": g("تحيز العينة", "جروب المتفوقين مش المدرسة. الصامتون وباقي الصفوف ومن بلا واتساب غابوا، فالميل من العينة مش من عدد الردود.", "استطلاع الواتساب يتكتب: رأي اللي ردوا في الجروب ده، مش رأي المدرسة.", "Sampling bias", "The honour-roll group is not the school. Silent members, other grades, and students without WhatsApp are missing, so the tilt is the sample, not the reply count.", "The WhatsApp poll is labelled: the view of those who replied in this group, not the school's view."),
  "5-1-a02": g("بيانات أولية وثانوية", "العد بنفسك يطابق غرضك ووقتك. جدول الجهة أسرع، لكن محتاج تاريخ الجهة وغرضها.", "عدّ عربيات البوابة يناسب سؤال اليوم. جدول الجهاز المركزي يناسب مقارنة سنين.", "Primary and secondary data", "Counting yourself matches your purpose and moment. An agency table is faster, but needs that agency's date and purpose.", "Counting cars at the gate fits today's question. A CAPMAS table fits a years-long comparison."),
  "5-1-a03": g("الاختيار الذاتي", "اللي بيحب يظهر بيرد، والصامتون بيختفوا. التعميم على الصف كله غلط.", "استطلاع الستوري يتكتب رأي اللي ضغطوا، مش رأي الصف.", "Self-selection", "Visibility-seekers reply and quiet students vanish. Generalising to the whole class fails.", "The story poll is labelled as those who tapped, not the class view."),
  "5-1-a04": g("مسار البحث", "جمع، بعدين تنظيم، بعدين تحليل. التواريخ والوحدات المختلطة بتخرب الناتج قبل القانون.", "أوراق الاستطلاع تترتّب وتتوحد وحداتها قبل أي متوسط أو رسم.", "Research path", "Collect, then organise, then analyse. Mixed dates and units break the output before the formula.", "Survey sheets are sorted and their units unified before any mean or chart."),
  "5-1-a05": g("العينة العشوائية والطبقية", "القرعة من قائمة واحدة فرصة متكافئة. الطبقية تحفظ كل صف فلا تختفي أولى ثانوي.", "لو الصفوف الثلاثة مهمين، نسحب من كل صف، مش قرعة واحدة ممكن تمسح صف.", "Simple random and stratified samples", "A lottery from one list gives equal chance. Stratified sampling keeps each grade present so Grade 10 is not erased.", "If all three grades matter, we draw from each grade, not one lottery that can wipe a grade."),
  "5-1-a06": g("العينة المريحة", "اللي بيطلع الساعة 1:30 مش المدرسة. غاب اللي بيفضل للحصة الأخيرة، فالمتوسط يميل لقصر اليوم.", "سؤال طول اليوم يتسأل في الحصص المختلفة، مش عند البوابة بعد الظهر بس.", "Convenience sampling", "1:30 gate leavers are not the school. Last-period stayers are missing, so the mean tilts toward a shorter day.", "Day-length is asked in different periods, not only at the afternoon gate."),
  "5-1-a07": g("المجتمع والعينة", "فصل واحد في العباسية مش كل مراهقي القاهرة. الادعاء واثق وغلط.", "نكتب: طلاب الفصل ده، مش كل مراهقي القاهرة.", "Population and sample", "One Abbasiya class is not every Cairo teenager. The claim is confident and wrong.", "We write: students in this class, not every Cairo teenager."),
  "5-1-a08": g("عدم الرد", "اللي ما ضغطش لسه جزء من المجتمع. حذفه يميل لمن عنده وقت أو رأي حاد.", "الاستطلاع يحسب الصامتين جزء من الصف، مش يمسحهم من المجتمع.", "Non-response", "Those who never tap stay in the population. Dropping them tilts toward time or sharp views.", "The poll keeps silent members as part of the class, and does not erase them from the population."),
  "5-2-a01": g("القيمة الناقصة", "الخلية الفاضية ممكن غياب مش صفر. الأسلم تعليم أو إعادة، مش صفر تلقائي ولا حذف أعمى.", "درجة الاختبار القصير الفارغة تتعلم غياب، وممكن إعادة، مش تتتحسب صفر من غير سؤال.", "Missing value", "A blank cell may be absence, not zero. The safest move is a flag or a retake, not auto-zero or a blind delete.", "The blank quiz mark is flagged as absence, and may be retaken, not scored zero with no question."),
  "5-2-a02": g("تنظيف البيانات", "حذف الصف يرمي الدرجة الكاملة. الملء من الخيال يكذب. التعليم يحفظ الصف ويكشف النقص.", "لو العنوان ناقص والدرجة موجودة، نعلّم العنوان ونسيب الدرجة.", "Data cleaning", "Deleting the row throws away a complete mark. Invented fill lies. A flag keeps the row and exposes the gap.", "If only the address is missing, we flag the address and keep the mark."),
  "5-2-a03": g("التكرار", "عصير الساعة 10 وخبز الساعة 2 عمليتين. الدمج يخفي مبيعات حقيقية باسم إزالة التكرار.", "إيصالا الكانتين يتسابوا اتنين لأن السلعة والوقت مختلفين.", "Duplicates", "Juice at 10:00 and bread at 14:00 are two events. Merging hides real sales under a dedupe label.", "The two canteen receipts stay two because the item and the time differ."),
  "5-2-a04": g("مدخلات سيئة مخرجات سيئة", "القانون ما بيغسلش الغلط. أصفار الغياب وصفوف اللصق بتخلّي المتوسط أنظف شكل وأكذب.", "قبل المتوسط نشيل الصفر الغلط واللصق المكرر.", "Garbage in, garbage out", "The formula does not wash the error. Absence zeros and pasted rows make a tidier-looking and falser mean.", "Before the mean we remove the false zero and the pasted duplicate."),
  "5-2-a05": g("القيمة الشاذة", "955 من 100 مستحيلة فتتصحح من الورقة. 198 سم ممكن حقيقة نادرة، تتقاس تاني ومش تتمسح تلقائي.", "درجة اللغة المستحيلة تترجع لكراسة الإجابة. طول لاعب السلة يتقاس مرة تانية.", "Outlier", "955 out of 100 is impossible so it is corrected from the paper. 198 cm may be a rare truth and is remeasured, not auto-deleted.", "The impossible Arabic mark goes back to the answer booklet. The basketball height is measured again."),
  "5-2-a06": g("توحيد الفئات", "ذكر وم وmale عند البرنامج فئات كتير لنفس المجموعة. التوحيد قبل المجموع واجب.", "عمود النوع يبقى كلمة واحدة قبل تقرير مجلس الأمناء.", "Unifying categories", "ذكر, م, and male look like extra groups to the program. Unification must precede the total.", "The gender column becomes one word before the governors' report."),
  "5-2-a07": g("التطبيع", "الثواني جنب عدد الوجبات من غير تحويل: المدى الكبير بيبلع الصغير.", "زمن الطابور وعدد الوجبات يتقاسوا بنفس المقياس قبل الرسم.", "Normalisation", "Queue seconds beside meal counts with no scaling lets the larger range swallow the smaller.", "Queue time and meal counts are put on the same scale before the chart."),
  "5-2-a08": g("توحيد التاريخ", "5/3/2026 و2026-03-05 و٥ مارس أيام منفصلة عند البرنامج. التوحيد قبل مجموع أيام المكتبة.", "عمود تاريخ المكتبة يبقى شكل واحد قبل أي عدد أيام.", "Unifying dates", "5/3/2026, 2026-03-05, and 5 March count as different days. Unification is an engineering step before the library-day total.", "The library-date column becomes one shape before any day count."),
  "5-3-a01": g("تاريخ التحديث", "ملف 2019 مش دخل 2026. من غير جملة قيد، الرقم القديم يتلبس ثوب الحاضر.", "تقرير الدخل يكتب سنة المصدر، أو يدور على رقم أحدث.", "Update date", "A 2019 file is not 2026 income. With no limiting sentence, a dead figure wears the clothes of now.", "The income report states the source year, or looks for a fresher figure."),
  "5-3-a02": g("واجهة برمجية وملف راكد", "الطلب الحي يعكس العقد الحالي. الملف المحفوظ الترم اللي فات يصلح لمقارنة تاريخية. الاتنين محتاجين مصدر ووقت.", "قبل خروج الرحلة نطلب مواعيد حية، ومش نعتمد ملف الترم الماضي لوحده.", "Live request and stale file", "A live request reflects today's contract. A file saved last term suits historical contrast. Both still need source and time.", "Before the trip leaves we request live times, and do not rely on last term's file alone."),
  "5-3-a03": g("توثيق المصدر", "مسح اسم الوزارة سرقة للجدول وبيقفل المراجعة. الأصالة في السؤال، مش في الشعار الممسوح.", "جدول جودة الهواء يفضل عليه اسم الجهة.", "Citing the source", "Erasing the ministry name steals the table and blocks checking. Originality sits in the question, not in a wiped logo.", "The air-quality table keeps the agency name."),
  "5-3-a04": g("الترخيص", "التحميل المجاني مش معناه إعادة النشر. جملة كل الحقوق محفوظة ممكن تمنع اللصق في مجلة المدرسة.", "قبل مجلة المدرسة نقرأ شروط الملف، ومش نلصق لأن التحميل كان مجاني.", "Licence", "A free download is not a right to republish. All rights reserved may block a paste into the school magazine.", "Before the magazine we read the file terms, and do not paste just because the download was free."),
  "5-3-a05": g("بيانات مفتوحة واستطلاع الصف", "المفتوح يوفّر وقت ونطاق أوسع. استطلاعك يطابق غرض الحصة. الاتنين محتاجين ترخيص أو منهج وتاريخ وتحيز.", "سؤال الزيارات يتقارن بجدول الجهة وباستطلاع الصف، والاتنين عليهم تاريخ.", "Open data and a class survey", "Open data saves time and covers a wider range. Your survey matches the class purpose. Both still need licence or method, date, and a bias check.", "The visits question is compared with the agency table and the class poll, and both carry a date."),
  "5-3-a06": g("التحيز", "الشعار الحكومي المفتوح مش بيلغي تعريف الزائر ولا موسم العينة.", "عرض الأهرام يقارن الملف الرسمي بمصدر تاني، ومش يقول بلا تحيز لأنه حكومي.", "Bias", "An official open logo does not cancel visitor definitions or sample season.", "The pyramid slide compares the official file with another source, and does not say unbiased because it is official."),
  "5-3-a07": g("تاريخ التحديث", "سنة التعداد قيد واجب. إخفاؤها بتحوّل رقم ميت لحاضر كاذب.", "البحث الصحي يكتب سنة التعداد جنب الرقم.", "Update date", "The census year is a required limit. Hiding it turns a dead figure into a false present.", "The health paper writes the census year beside the number."),
  "5-3-a08": g("توثيق المصدر", "البوابة ممكن تتغير بكرة. التاريخ يثبت النسخة اللي شفتها، والاسم يمنع ادعاء الملكية.", "ذيل تقرير الكهرباء يكتب اسم الجهة وتاريخ الدخول حتى لو الرابط ظاهر.", "Citing the source", "The portal may change tomorrow. The date pins the version you saw, and the name blocks a claim of ownership.", "The electricity-report footer keeps the agency name and access date even when the link is visible."),

  "6-1-a01": g("المتوسط والوسيط", "الـ 98 بيسحب المتوسط لفوق. الوسيط يفضل قرب 12–13 ويوصف مركز الصف. الملخص محتاج أكتر من رقم.", "نكتب الوسيط جنب المتوسط عشان درجة واحدة عالية ما تخدعش القارئ.", "Mean and median", "The 98 pulls the mean up. The median stays near 12–13 and shows the class centre. A summary needs more than one number.", "We write the median beside the mean so one high mark does not fool the reader."),
  "6-1-a02": g("وصف واستدلال", "تلخيص شعبة واحدة وصف للعينة. تعميمه على المدرسة استدلال محتاج تمثيل وعدم يقين.", "متوسط حضور الشعبة يتكتب للشعبة دي، مش للمدرسة كلها من غير ما نسأل مين غاب عن العينة.", "Description and inference", "Summarising one class describes the sample. Generalising it to the school is inference and needs representativeness and uncertainty.", "The class attendance mean is written for this class, not for the whole school without asking who is missing from the sample."),
  "6-1-a03": g("ارتباط مش سببية", "استخدام التطبيق والدرجة ممكن يتحركوا مع الالتزام السابق. من غير مقارنة أو قبل/بعد، السبب مش ثابت.", "جملة التطبيق بيرفع الدرجة تتبدل: اللي بيستخدمه درجته أعلى، والسبب لسه مش معروف.", "Correlation is not causation", "App use and marks may both move with prior commitment. Without a comparison group or before/after, cause is not proven.", "The sentence becomes: heavier users have higher marks, and the cause is still unknown."),
  "6-1-a04": g("فترة الثقة", "ست قراءات بتوسّع المدى لأن العينة صغيرة. معدل السنة ما يتعلنش رقم قاطع من غير عدد القراءات وعرض الفترة.", "إعلان المطر يكتب عدد القراءات ويعترف إن الست أوسع من الستين.", "Confidence interval", "Six readings widen the range because the sample is small. A yearly rate is not shouted as a final number without n and the interval width.", "The rain announcement states the reading count and admits that six is wider than sixty."),
  "6-1-a05": g("الفرضية", "الادعاء يتختبر بعدد الصفحات أو الاستعارات، مع مقارنة بمقاعد تانية، مش بإحساس الردهة.", "فرضية النافذة تتقاس: كام صفحة أو استعارة جنب الشباك مقابل باقي المقاعد.", "Hypothesis", "The claim is tested with page or loan counts, compared with other seats, not with a hallway feeling.", "The window claim is measured: pages or loans by the window versus the other seats."),
  "6-1-a06": g("فترة الثقة", "عينة خمسة عادة أوسع من أربعين. منساوش الدقتين، ومنضيّقش الصغيرة بإيدنا.", "مصروف الكانتين من خمسة طلاب يتكتب بمدى أوسع، مش كأنه دقيق زي الأربعين.", "Confidence interval", "An n=5 interval is usually wider than n=40. Do not equate the two precisions or narrow the small one by hand.", "Canteen spend from five students is written with a wider range, not as if it were as precise as forty."),
  "6-1-a07": g("الاستدلال", "يوم ممطر واحد مش السنة: الطقس والمناسبات بتتغير. نضيّق الادعاء أو نزود الأيام.", "مبيعات العصير تتكتب لليوم ده، مش لمبيعات السنة كلها.", "Inference", "One rainy day does not resemble the year: weather and events change. Narrow the claim or add more days.", "Juice sales are written for that day, not for the whole year's sales."),
  "6-1-a08": g("المتوسط والوسيط", "أسبوع الإنفلونزا بيسحب متوسط الغياب. الوسيط أقرب للأسابيع العادية، والأسبوع الشاذ يتعلّم ومش يتتخبّى.", "الملخص الشهري يكتب الوسيط ويذكر أسبوع المرض.", "Mean and median", "A flu week pulls the monthly mean. The median stays closer to ordinary weeks, and the unusual week is flagged, not hidden.", "The monthly summary writes the median and names the illness week."),
  "6-2-a01": g("خط الاتجاه", "لو مفيش اتجاه متوقع، البواقي كبيرة والخط ضعيف. سحابة أنواع الوجبات مقابل الحرارة غالبًا ضجيج.", "متحطش خط مستقيم على رسم الوجبات والحرارة لو النقاط مبعثرة من غير قصة.", "Trend line", "If you do not expect a trend, residuals will be large and the line is weak. A cloud of snack types versus temperature is often noise.", "Do not draw a straight line on snack type versus temperature if the points are scattered with no story."),
  "6-2-a02": g("الاستكمال", "5 ساعات جوه مدى 1–8 وصف حذر. 40 ساعة برة النقاط توقع خطر.", "نتوقع الدرجة عند خمس ساعات مذاكرة، ومش نمد الخط لحد أربعين.", "Extrapolation", "Five hours inside a 1–8 range is a cautious description. Forty hours beyond the points is a risky forecast.", "We predict the mark at five study hours, and do not stretch the line to forty."),
  "6-2-a03": g("ارتباط مش سببية", "الخط بيوصف اقتران التأخير والدرجة. النوم أو الأتوبيس أو الالتزام ممكن يحركوا الاتنين.", "جملة الخط بيثبت إن التأخير بيسبب الرسوب تتبدل: في اقتران، والسبب لسه مش ثابت.", "Correlation is not causation", "The line describes a pairing of lateness and marks. Sleep, the bus, or commitment may move both.", "The sentence becomes: there is a pairing, and cause is not proven."),
  "6-2-a04": g("البواقي", "الباقي = الواقع − الخط. لو كبير ومتفرق، الخط مش ماسك النقاط. الصغر جودة ملاءمة مش سببية.", "ساعات العمل بعد المدرسة لو النقاط بعيدة عن الخط، الخط ضعيف.", "Residuals", "Residual = reality minus the line. If they are large and scattered, the line does not hold the points. Small residuals are fit quality, not cause.", "If after-school hours sit far from the line, the line is weak."),
  "6-2-a05": g("المتغير التفسيري", "مقاس الحذاء مالوش آلية معقولة مع درجة الرياضيات. العمر ممكن يحرّك الاتنين.", "نرفض الحذاء كسبب للدرجة حتى لو ظهر اقتران ضعيف.", "Explanatory variable", "Shoe size has no sensible mechanism for the maths mark. Age may move both.", "We reject shoe size as a cause of the mark even if a weak pairing appears."),
  "6-2-a06": g("المتغير التفسيري", "الحرارة قصة معقولة لمبيعات العصير بعد فحص البواقي. عدد نادي الشطرنج مالوش قصة مع حرارة السطح.", "المنطق الأول، بعدين الملاءمة. الشطرنج مش متغير لتوقع الحرارة.", "Explanatory variable", "Temperature is a plausible predictor of juice sales, then checked by residuals. Chess-club headcount has no story for roof temperature.", "Sense first, then fit. Chess-club size is not a predictor of roof heat."),
  "6-2-a07": g("الاستكمال", "مبيعات الفسحة من 10 لـ 10:20 مش عادة الثالثة فجرًا. الساعة والسياق برة المدى.", "نتوقع مبيعات الحفلة من بيانات الحفلة، مش من خط الفسحة.", "Extrapolation", "Break sales from 10:00 to 10:20 are not a 3 a.m. habit. The hour and the setting sit outside the range.", "Party sales are forecast from party data, not from the break-time line."),
  "6-2-a08": g("ارتباط مش سببية", "حتى لو البواقي صغيرة، الخط وصف. الزيارة مش بالضرورة سبب الدرجة.", "خط المكتبة والدرجة يتكتب وصف للاقتران، مش دليل إن الزيارة رفعت الدرجة.", "Correlation is not causation", "Even with small residuals the line stays a description. Visits do not automatically cause the mark.", "The library-and-mark line is written as a pairing, not as proof that visits raised the mark."),
  "6-3-a01": g("قطع المحور", "البدء من 70 بيضخّم فرق نقطتين بين 71 و73. نبدأ من صفر أو نصرّح بالقطع ونكتب النسب.", "رسم النجاح يبدأ من صفر، أو يقول إن المحور مقطوع ويكتب 71٪ و73٪.", "Cropped axis", "Starting at 70 inflates a two-point gap between 71 and 73. Start at zero or declare the crop and write the rates.", "The pass-rate chart starts at zero, or says the axis is cropped and writes 71% and 73%."),
  "6-3-a02": g("اختيار الرسم", "السؤال تتبع غياب عبر الزمن: الخط أنسب. الأعمدة تنفع لو الأسابيع مترتبة. الدائرة بعشرات الشرائح ضعيفة.", "غياب الترم يترسم خطًا أسبوعيًا، مش دائرة.", "Choosing the chart", "The question tracks absences over time: a line serves it. Bars can work if weeks are ordered. A pie with dozens of slices is weak.", "Term absences are drawn as a weekly line, not a pie."),
  "6-3-a03": g("الدائرة", "عشرين شريحة مش بتتقري. الأعمدة المرتبة أو تجميع الأندية الصغيرة أوضح. الدائرة لأجزاء قليلة من كل.", "عضوية عشرين نادي تبقى أعمدة، مش دائرة واحدة.", "Pie chart", "Twenty slices cannot be read. Sorted bars or grouping tiny clubs are clearer. A pie is for a few parts of a whole.", "Twenty-club membership becomes bars, not one pie."),
  "6-3-a04": g("اختيار الرسم", "نحدد السؤال أولًا: فئات، زمن، ولا أجزاء كل؟ الجمال من غير محور أو بمصدر مخفي بيضلّل.", "تقرير الكانتين يختار الرسم اللي بيرد على السؤال، مش الألمح.", "Choosing the chart", "Name the question first: categories, time, or parts of a whole? Pretty charts with no axis or a hidden source mislead.", "The canteen report picks the chart that answers the question, not the shiniest one."),
  "6-3-a05": g("المصدر والمحاور", "من غير مصدر وتاريخ مفيش مراجعة. من غير أسماء محاور مش معروف المطر يوم ولا شهر.", "رسم مطر الملعب يكتب المصدر وتاريخه ويسمّي المحاور.", "Source and axes", "No check is possible without a source and a date. Unlabelled axes hide whether the rain is a day or a month.", "The pitch-rain chart writes the source and date and names the axes."),
  "6-3-a06": g("عنوان الرسم", "العنوان اللي بيصرّح بالادعاء يتفحص. شكل 2 رقم مش بيفيد السؤال.", "نكتب ارتفع النجاح بعد حصص الدعم لو ده الادعاء، ومش نسيب العنوان شكل 2.", "Chart title", "A title that states a claim can be tested. Figure 2 is a number that does not serve the question.", "We write pass rates rose after support lessons if that is the claim, and do not leave the title as Figure 2."),
  "6-3-a07": g("الدائرة ثلاثية الأبعاد", "البعد الثالث بيضخّم شريحة ويصغّر تانية. الشعب فئات مستقلة تناسبها أعمدة من صفر مع مصدر.", "غياب ثلاث شعب أعمدة من صفر، مش دائرة مجسّمة.", "3D pie", "The third dimension inflates one slice and shrinks another. Separate classes suit bars from zero, with a source.", "Absences in three classes become bars from zero, not a 3D pie."),
  "6-3-a08": g("قطع المحور", "الارتفاع من 9.0 لـ 9.2 فرق تافه. القطع عند 8.9 بيصنعه أزمة بصرية.", "سعر الوجبة يترسم من صفر، أو الفرق يتكتب صراحة مع المصدر.", "Cropped axis", "A rise from 9.0 to 9.2 is a tiny gap. Cropping at 8.9 turns it into a visual crisis.", "The meal price is drawn from zero, or the gap is written plainly with the source."),

  "7-1-a01": g("تعلم بإشراف", "البيض فئتين معلّمتين: للكسر أو للتفريخ. كل صورة لازم تحمل المثال ونتيجته. الصور من غير تسمية مش تدريب.", "المزرعة تعلّم النموذج بصور مكتوب عليها صالح للكسر أو للتفريخ.", "Supervised learning", "Eggs are two labeled classes: cracking or hatching. Each photo must carry the example and its result. Unlabeled photos are not training.", "The farm trains the model with photos marked cracking or hatching."),
  "7-1-a02": g("التصنيف والانحدار", "يحضر أو يغيب فئة: تصنيف. دقائق الانتظار رقم: انحدار. السؤال هو اللي يختار العمود، مش شكل الجدول.", "جدول العيادة الواحد يخدم سؤالين مختلفين حسب العمود المستهدف.", "Classification and regression", "Attends or misses is a class: classification. Waiting minutes is a number: regression. The question picks the target column, not the look of the table.", "One clinic table serves two different questions according to the target column."),
  "7-1-a03": g("مجموعة الاختبار", "الاختبار على نفس أوراق التدريب درجة متفائلة كاذبة. المدرسة الأخرى توزيع مختلف.", "نسيب جزء من الأوراق ما تشافش في التعلم، ومش نعلن الجاهزية لمدرسة تانية من درجة الصف.", "Test set", "Testing on the training papers gives a falsely optimistic score. The other school is a different distribution.", "We keep papers the model has not seen, and do not declare readiness for another school from the class score."),
  "7-1-a04": g("تحيز البيانات", "لو كل علب التدريب من حي واحد، النموذج يكرر رفض الحي ده. الحاسوب مش بيعدّل العدالة لوحده.", "جودة المصنع تتدرّب من أحياء مختلفة، مش من حي واحد.", "Data bias", "If every training can came from one district, the model keeps rejecting that district. A computer does not repair fairness by itself.", "Factory quality is trained from several districts, not from one."),
  "7-1-a05": g("تجميع بلا إشراف", "النموذج يبرز تجمعات من القياسات. التشخيص والتسمية قرار الطبيب. مفيش عمود مخرج يبقى مفيش دقة شفاء.", "عيادة من غير تشخيص مكتوب تستخدم التجميع كاقتراح مجموعات، والطبيب يسمّي.", "Unsupervised clustering", "The model highlights groups from measurements. Naming a diagnosis stays with the doctor. With no output column there is no cure score.", "A clinic with no written diagnosis uses clustering as suggested groups, and the doctor names them."),
  "7-1-a06": g("تعلم بإشراف وبلا إشراف", "ناجح/راسب مخرج معروف: بإشراف. مجموعات أساليب المذاكرة من غير نتيجة: بلا إشراف. متتحسبوش بنفس الأداة.", "مشروع الرسوب يتقاس بدقة على مجموعة اختبار. مشروع العادات يتوصف بالتجمعات بس.", "Supervised and unsupervised learning", "Pass or fail is a known output: supervised. Study-habit groups with no outcome column: unsupervised. Do not score both with one tool.", "The fail project is scored on a test set. The habits project is described by its groups only."),
  "7-1-a07": g("مجموعة الاختبار", "دقة 100٪ على خط التدريب حفظ، مش جودة وردية جديدة.", "ملصق المصنع يطلب مجموعة اختبار النموذج ما شافهاش، مش يكتب 100٪ على خط التدريب.", "Test set", "100% on the training line is memorization, not quality on a new shift.", "The factory poster demands a test set the model has not seen, and does not write 100% on the training line."),
  "7-1-a08": g("فصل التدريب عن الاختبار", "صور يناير للتعلم وصور مارس للقياس الصادق. إعادة استخدام يناير تفاؤل كاذب.", "كاشف الكسور يتعلم من شهر ويختبر من شهر تاني ما دخلش التعلم.", "Train–test split", "January scans train and March scans measure honestly. Reusing January yields false optimism.", "The fracture detector learns from one month and is tested on a later month that never entered learning."),
  "7-2-a01": g("التمثيل العميق", "كل طبقة بتلخّص اللي قبلها: حافة، بعدين شكل الثمرة، بعدين قرار القطف. القرار الأخير مش جملة سحرية في أول طبقة.", "كاميرا الحصاد تعدّي الصورة طبقات لحد قرار القطف.", "Deep representation", "Each layer summarises the one before it: edge, then fruit shape, then the pick decision. The last decision is not a magic sentence in the first layer.", "The harvest camera passes the photo through layers until the pick decision."),
  "7-2-a02": g("عمق الشبكة", "عشر طبقات على عشرة صفوف عمق من غير بيانات. الجدول الصغير يناسب خط أبسط وأوضح للمساءلة.", "حرارة الفرن القليلة تناسب خط بسيط، مش شبكة عميقة.", "Network depth", "Ten layers on ten rows is depth without data. A tiny table fits a simpler line that is easier to hold to account.", "The small kiln table uses a simple line, not a deep net."),
  "7-2-a03": g("الصندوق الأسود", "لما القرار يمس حياة، الرقم الصامت مش كفاية. نطلب سبب قابل للمراجعة وبيانات كافية.", "المستشفى ما يرفضش العملية من درجة خطر من غير شرح.", "Black box", "When the decision touches a life, a silent number is not enough. Demand a reviewable reason and enough data.", "The hospital does not deny surgery from a risk score with no explanation."),
  "7-2-a04": g("الأوزان", "التعلم بيعدّل وزن كل قناة. حساس كان ضعيف ممكن يتصدق أكتر بعد أمثلة الضرر.", "قرار الري يتغير بعد أسابيع لأن الأوزان اتعدلت، حتى لو الحساسات هي هي.", "Weights", "Learning adjusts the weight of each channel. A weak sensor may be trusted more after damage examples.", "The irrigation decision changes after weeks because the weights moved, even if the sensors stayed the same."),
  "7-2-a05": g("الصندوق الأسود", "قرار المنحة يغيّر مسار إنسان، فمحتاج تفسير طبقة القرار مش رقم صامت للأهل.", "فصل الطالب من المنحة يتكتب بسببه، مش بدرجة خطر عميقة بس.", "Black box", "A scholarship decision changes a path, so it needs an explanation of the decision layer, not a silent number for the family.", "Dropping the student is written with a reason, not only a deep risk score."),
  "7-2-a06": g("العصبون والشبكة", "العصبون جمع موزون لحرارة ورطوبة. الشبكة تكدّس طبقات لصورة أغنى، وتحتاج بيانات أكبر.", "مزرعة الدواجن ممكن تبدأ بعصبنون رقمين. قراءة صورة القطيع محتاجة شبكة وبيانات أكتر.", "Neuron and network", "A neuron is a weighted sum of heat and humidity. A network stacks layers for a richer photo representation and needs more data.", "The poultry house can start with one neuron on two numbers. Reading a flock photo needs a net and more data."),
  "7-2-a07": g("عمق الشبكة", "عشرين صورة جنب المدرسة مش بتشيل قيادة ذاتية عميقة. العمق من غير بيانات يفشل وقد يؤذي.", "اقتراح القيادة العميقة يترفض لحد ما تتوفر بيانات كافية.", "Network depth", "Twenty street photos beside the school do not buy a deep self-driving net. Depth without data fails and can harm.", "The deep driving proposal is refused until there is enough data."),
  "7-2-a08": g("الصندوق الأسود", "ترتيب الجرحى حياة بشرية. جملة لا أحد يفهم الداخل علامة خطر أخلاقية، مش تقدم.", "نموذج ترتيب المصابين لازم يبقى قابل للمراجعة، مش مصدر فخر بالغموض.", "Black box", "Ranking casualties is human lives. Boasting that nobody understands the inside is an ethical warning, not progress.", "The casualty-ranking model must stay reviewable, not a boast of opacity."),
  "7-3-a01": g("توقع الرمز التالي", "النموذج بيكمل الكلمة الجاية، مش بيعرف الغيب. الرقم الواثق أسلوب مش معرفة الدرجة.", "جملة عرف درجتي قبل التصحيح تتصلح: كتب رقم واثق، من غير ما يكون شاف الورقة.", "Next-token prediction", "The model completes the next word; it does not know the future. A confident number is style, not knowledge of the mark.", "The claim he knew my mark is corrected: it wrote a confident number without seeing the paper."),
  "7-3-a02": g("توجيه الأمر", "الأمر الضيّق يغيّر التكملة ويرفع الجودة. اشرح لوحدها بترد كلام عام.", "نكتب: اشرح درس الشبكات لصف ثاني ثانوي بمثال مزرعة، مش اشرح بس.", "Prompting", "A tighter ask changes the completion and raises quality. Explain alone returns generic talk.", "We write: explain the networks lesson to a second-year class with a farm example, not explain alone."),
  "7-3-a03": g("الاستخدام السليم", "تشرح لنفسك بعدين تكتب صوتك. لصق فقرة النموذج في الواجب بيلغي المسؤولية.", "واجب التصنيف والانحدار يتقفل فيه الشات ويتكتب بالفهم.", "Sound use", "Explain to yourself, then write in your voice. Pasting the model's paragraph removes academic responsibility.", "Classification-versus-regression homework is written from understanding after the chat is closed."),
  "7-3-a04": g("الهلوسة", "جملة مدى إنزيم فصيحة ممكن تكون شكل طبي من غير سند المختبر. الفصاحة مش دليل صدق.", "خطاب الخروج يتراجع على أرقام القسم، ومش يعتمد جملة النموذج لوحدها.", "Hallucination", "A fluent enzyme-range sentence may be a medical look with no local lab grounding. Fluency is not proof of truth.", "The discharge note is checked against the department's numbers, and does not trust the model's sentence alone."),
  "7-3-a05": g("الفصاحة مش صدق", "سلاسة الجملة إكمال رموز. تعليمات التشغيل محتاجة مهندس ومصدر.", "ملصق المصنع يتراجع فنيًا، مش يتطبع لأن اللغة سلسة.", "Fluency is not truth", "A smooth sentence is token completion. Operating instructions need an engineer and a source.", "The factory poster is checked by a technician, and is not printed because the language is fluent."),
  "7-3-a06": g("الاستخدام السليم", "فهم فكرة الرطوبة بعدين القياس في الحقل تعلم ثم عمل بشري. استخدام النموذج كمحطة أرصاد يخلط التكملة بالمعرفة.", "الطالب يفهم الفكرة من النموذج ويقيس في الحقل، ومش يخلّي الشات يقرر الري.", "Sound use", "Understanding moisture then measuring in the field is learning then human work. Using the model as a weather station mixes completion with knowledge.", "The student learns the idea from the model and measures in the field, and does not let chat order irrigation."),
  "7-3-a07": g("الخصوصية", "بطاقة المريض وكشف الدرجات أسرار. اللي يتلصق في الشات ممكن يتتحفظ في مكان غلط.", "مترفعش صورة البطاقة ولا كشف الصف لتخصيص الرد.", "Privacy", "A patient ID and a class mark sheet are secrets. Whatever you paste may be stored where it should not be.", "Do not upload the ID photo or the class sheet to personalise the reply."),
  "7-3-a08": g("مراجعة بشرية", "سلسلة الرموز تفضّل جملة مكتملة على جملة صادقة. سبب الحادث يتكتب من محضر الوردية.", "فني السلامة يراجع كل كلمة في الحادث سببه قبل التوقيع، ومش يعتمد تكملة النموذج.", "Human review", "A token chain prefers a finished sentence over a true one. The cause is written from the shift record.", "The safety tech reviews every word in the accident was caused by… before signing, and does not trust the model's completion."),
};
